import { revalidateTag } from "next/cache";
import { after } from "next/server";
import { getCachedProducts } from "@/lib/products";

async function syncCatalogAction() {
  "use server";
  after(async () => {
    await new Promise((resolve) => setTimeout(resolve, 1500));
    revalidateTag("products");
  });
  return { syncing: true };
}

export default async function Page() {
  const products = await getCachedProducts();

  return (
    <div className="min-h-screen bg-zinc-50">
      <header className="border-b border-zinc-200 bg-white px-6 py-4">
        <div className="mx-auto flex max-w-5xl items-center justify-between">
          <h1 className="text-xl font-semibold text-zinc-900">
            Admin Product Catalog
          </h1>
          <form action={syncCatalogAction}>
            <button
              type="submit"
              className="rounded-md bg-zinc-900 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-zinc-800 focus:outline-none focus:ring-2 focus:ring-zinc-500 focus:ring-offset-2"
            >
              Sync latest catalog
            </button>
          </form>
        </div>
      </header>

      <main className="mx-auto max-w-5xl px-6 py-8">
        <p className="mb-6 text-sm text-zinc-500">
          Catalog data is cached for fast browsing. Use &quot;Sync latest
          catalog&quot; when upstream ERP/PIM data changes. The sync runs in the
          background—you can keep working while it completes.
        </p>

        <div className="overflow-hidden rounded-lg border border-zinc-200 bg-white shadow-sm">
          <table className="min-w-full divide-y divide-zinc-200">
            <thead>
              <tr>
                <th className="bg-zinc-50 px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                  ID
                </th>
                <th className="bg-zinc-50 px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                  Product
                </th>
                <th className="bg-zinc-50 px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                  Price
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-200 bg-white">
              {products.map((product) => (
                <tr key={product.id}>
                  <td className="whitespace-nowrap px-6 py-4 text-sm text-zinc-900">
                    {product.id}
                  </td>
                  <td className="whitespace-nowrap px-6 py-4 text-sm font-medium text-zinc-900">
                    {product.name}
                  </td>
                  <td className="whitespace-nowrap px-6 py-4 text-sm text-zinc-600">
                    ${product.price.toLocaleString()}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </main>
    </div>
  );
}

